import{_ as i,a0 as l,w as p,s as a,I as t,x as o,a1 as n,A as s,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 中使用日志来排错 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中使用日志来排错 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中使用日志来排错 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中使用日志来排错 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150803 Troubleshooting with Linux Logs","title":"在 Linux 中使用日志来排错","tag":"201508","desc":""},"relativePath":"201508/20150803 Troubleshooting with Linux Logs.md","filePath":"[post].md"}'),d={name:"201508/20150803 Troubleshooting with Linux Logs.md"};function g(m,e,h,f,x,b){const r=l("Link");return p(),a("div",null,[e[20]||(e[20]=t("h1",{id:"在-linux-中使用日志来排错",tabindex:"-1"},[o("在 Linux 中使用日志来排错 "),t("a",{class:"header-anchor",href:"#在-linux-中使用日志来排错","aria-label":"Permalink to “在 Linux 中使用日志来排错”"},"​")],-1)),e[21]||(e[21]=t("p",null,"人们创建日志的主要原因是排错。通常你会诊断为什么问题发生在你的 Linux 系统或应用程序中。错误信息或一系列的事件可以给你提供找出根本原因的线索，说明问题是如何发生的，并指出如何解决它。这里有几个使用日志来解决的样例。",-1)),e[22]||(e[22]=t("h3",{id:"登录失败原因",tabindex:"-1"},[o("登录失败原因 "),t("a",{class:"header-anchor",href:"#登录失败原因","aria-label":"Permalink to “登录失败原因”"},"​")],-1)),t("p",null,[e[1]||(e[1]=o("如果你想检查你的系统是否安全，你可以在验证日志中检查登录失败的和登录成功但可疑的用户。当有人通过不正当或无效的凭据来登录时会出现认证失败，这通常发生在使用 SSH 进行远程登录或 su 到本地其他用户来进行访问权时。这些是由",-1)),n(r,{href:"http://linux.die.net/man/8/pam.d"},{default:s(()=>[...e[0]||(e[0]=[o("插入式验证模块（PAM）",-1)])]),_:1}),e[2]||(e[2]=o("来记录的。在你的日志中会看到像 Failed password 和 user unknown 这样的字符串。而成功认证记录则会包括像 Accepted password 和 session opened 这样的字符串。",-1))]),e[23]||(e[23]=u(`<p>失败的例子:</p><pre><code>pam_unix(sshd:auth): authentication failure; logname= uid=0 euid=0 tty=ssh ruser= rhost=10.0.2.2
Failed password for invalid user hoover from 10.0.2.2 port 4791 ssh2
pam_unix(sshd:auth): check pass; user unknown
PAM service(sshd) ignoring max retries; 6 &gt; 3
</code></pre><p>成功的例子：</p><pre><code>Accepted password for hoover from 10.0.2.2 port 4792 ssh2
pam_unix(sshd:session): session opened for user hoover by (uid=0)
pam_unix(sshd:session): session closed for user hoover
</code></pre><p>你可以使用 grep 来查找哪些用户失败登录的次数最多。这些都是潜在的攻击者正在尝试和访问失败的账户。这是一个在 ubuntu 系统上的例子。</p><pre><code>$ grep &quot;invalid user&quot; /var/log/auth.log | cut -d &#39; &#39; -f 10 | sort | uniq -c | sort -nr
23 oracle
18 postgres
17 nagios
10 zabbix
6 test
</code></pre><p>由于没有标准格式，所以你需要为每个应用程序的日志使用不同的命令。日志管理系统，可以自动分析日志，将它们有效的归类，帮助你提取关键字，如用户名。</p><p>日志管理系统可以使用自动解析功能从 Linux 日志中提取用户名。这使你可以看到用户的信息，并能通过点击过滤。在下面这个例子中，我们可以看到，root 用户登录了 2700 次之多，因为我们筛选的日志仅显示 root 用户的尝试登录记录。</p><p><img src="http://www.loggly.com/ultimate-guide/wp-content/uploads/2015/05/Screen-Shot-2015-03-12-at-11.05.36-AM.png" alt=""></p><p>日志管理系统也可以让你以时间为做坐标轴的图表来查看，使你更容易发现异常。如果有人在几分钟内登录失败一次或两次，它可能是一个真正的用户而忘记了密码。但是，如果有几百个失败的登录并且使用的都是不同的用户名，它更可能是在试图攻击系统。在这里，你可以看到在3月12日，有人试图登录 Nagios 几百次。这显然​​不是一个合法的系统用户。</p><p><img src="http://www.loggly.com/ultimate-guide/wp-content/uploads/2015/05/Screen-Shot-2015-03-12-at-11.12.18-AM.png" alt=""></p><h3 id="重启的原因" tabindex="-1">重启的原因 <a class="header-anchor" href="#重启的原因" aria-label="Permalink to “重启的原因”">​</a></h3><p>有时候，一台服务器由于系统崩溃或重启而宕机。你怎么知道它何时发生，是谁做的？</p><h4 id="关机命令" tabindex="-1">关机命令 <a class="header-anchor" href="#关机命令" aria-label="Permalink to “关机命令”">​</a></h4><p>如果有人手动运行 shutdown 命令，你可以在验证日志文件中看到它。在这里，你可以看到，有人从 IP 50.0.134.125 上作为 ubuntu 的用户远程登录了，然后关闭了系统。</p><pre><code>Mar 19 18:36:41 ip-172-31-11-231 sshd[23437]: Accepted publickey for ubuntu from 50.0.134.125 port 52538 ssh
Mar 19 18:36:41 ip-172-31-11-231 23437]:sshd[ pam_unix(sshd:session): session opened for user ubuntu by (uid=0)
Mar 19 18:37:09 ip-172-31-11-231 sudo:   ubuntu : TTY=pts/1 ; PWD=/home/ubuntu ; USER=root ; COMMAND=/sbin/shutdown -r now
</code></pre><h4 id="内核初始化" tabindex="-1">内核初始化 <a class="header-anchor" href="#内核初始化" aria-label="Permalink to “内核初始化”">​</a></h4><p>如果你想看看服务器重新启动的所有原因（包括崩溃），你可以从内核初始化日志中寻找。你需要搜索内核类（kernel）和 cpu 初始化（Initializing）的信息。</p><pre><code>Mar 19 18:39:30 ip-172-31-11-231 kernel: [    0.000000] Initializing cgroup subsys cpuset
Mar 19 18:39:30 ip-172-31-11-231 kernel: [    0.000000] Initializing cgroup subsys cpu
Mar 19 18:39:30 ip-172-31-11-231 kernel: [    0.000000] Linux version 3.8.0-44-generic (buildd@tipua) (gcc version 4.6.3 (Ubuntu/Linaro 4.6.3-1ubuntu5) ) #66~precise1-Ubuntu SMP Tue Jul 15 04:01:04 UTC 2014 (Ubuntu 3.8.0-44.66~precise1-generic 3.8.13.25)
</code></pre><h3 id="检测内存问题" tabindex="-1">检测内存问题 <a class="header-anchor" href="#检测内存问题" aria-label="Permalink to “检测内存问题”">​</a></h3><p>有很多原因可能导致服务器崩溃，但一个常见的原因是内存用尽。</p><p>当你系统的内存不足时，进程会被杀死，通常会杀死使用最多资源的进程。当系统使用了所有内存，而新的或现有的进程试图使用更多的内存时就会出现错误。在你的日志文件查找像 Out of Memory 这样的字符串或类似 kill 这样的内核警告信息。这些信息表明系统故意杀死进程或应用程序，而不是允许进程崩溃。</p><p>例如:</p><pre><code>[33238.178288] Out of memory: Kill process 6230 (firefox) score 53 or sacrifice child
[29923450.995084] select 5230 (docker), adj 0, size 708, to kill
</code></pre><p>你可以使用像 grep 这样的工具找到这些日志。这个例子是在 ubuntu 中:</p><pre><code>$ grep “Out of memory” /var/log/syslog
 [33238.178288] Out of memory: Kill process 6230 (firefox) score 53 or sacrifice child
</code></pre><p>请记住，grep 也要使用内存，所以只是运行 grep 也可能导致内存不足的错误。这是另一个你应该中央化存储日志的原因！</p><h3 id="定时任务错误日志" tabindex="-1">定时任务错误日志 <a class="header-anchor" href="#定时任务错误日志" aria-label="Permalink to “定时任务错误日志”">​</a></h3><p>cron 守护程序是一个调度器，可以在指定的日期和时间运行进程。如果进程运行失败或无法完成，那么 cron 的错误出现在你的日志文件中。具体取决于你的发行版，你可以在 /var/log/cron，/var/log/messages，和 /var/log/syslog 几个位置找到这个日志。cron 任务失败原因有很多。通常情况下，问题出在进程中而不是 cron 守护进程本身。</p><p>默认情况下，cron 任务的输出会通过 postfix 发送电子邮件。这是一个显示了该邮件已经发送的日志。不幸的是，你不能在这里看到邮件的内容。</p><pre><code>Mar 13 16:35:01 PSQ110 postfix/pickup[15158]: C3EDC5800B4: uid=1001 from=&lt;hoover&gt;
Mar 13 16:35:01 PSQ110 postfix/cleanup[15727]: C3EDC5800B4: message-id=&lt;20150310110501.C3EDC5800B4@PSQ110&gt;
Mar 13 16:35:01 PSQ110 postfix/qmgr[15159]: C3EDC5800B4: from=&lt;hoover@loggly.com&gt;, size=607, nrcpt=1 (queue active)
Mar 13 16:35:05 PSQ110 postfix/smtp[15729]: C3EDC5800B4: to=&lt;hoover@loggly.com&gt;, relay=gmail-smtp-in.l.google.com[74.125.130.26]:25, delay=4.1, delays=0.26/0/2.2/1.7, dsn=2.0.0, status=sent (250 2.0.0 OK 1425985505 f16si501651pdj.5 - gsmtp)
</code></pre><p>你可以考虑将 cron 的标准输出记录到日志中，以帮助你定位问题。这是一个你怎样使用 logger 命令重定向 cron 标准输出到 syslog的例子。用你的脚本来代替 echo 命令，helloCron 可以设置为任何你想要的应用程序的名字。</p><pre><code>*/5 * * * * echo ‘Hello World’ 2&gt;&amp;1 | /usr/bin/logger -t helloCron
</code></pre><p>它创建的日志条目：</p><pre><code>Apr 28 22:20:01 ip-172-31-11-231 CRON[15296]: (ubuntu) CMD (echo &#39;Hello World!&#39; 2&gt;&amp;1 | /usr/bin/logger -t helloCron)
Apr 28 22:20:01 ip-172-31-11-231 helloCron: Hello World!
</code></pre><p>每个 cron 任务将根据任务的具体类型以及如何输出数据来记录不同的日志。</p><p>希望在日志中有问题根源的线索，也可以根据需要添加额外的日志记录。</p><hr>`,38)),t("p",null,[e[4]||(e[4]=o("via: ",-1)),n(r,{href:"http://www.loggly.com/ultimate-guide/logging/troubleshooting-with-linux-logs/"},{default:s(()=>[...e[3]||(e[3]=[o("http://www.loggly.com/ultimate-guide/logging/troubleshooting-with-linux-logs/",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=o("作者：",-1)),n(r,{href:"https://www.linkedin.com/in/jasonskowronski"},{default:s(()=>[...e[5]||(e[5]=[o("Jason Skowronski",-1)])]),_:1}),e[11]||(e[11]=o(" 作者：",-1)),n(r,{href:"https://www.linkedin.com/in/amyecheverri"},{default:s(()=>[...e[6]||(e[6]=[o("Amy Echeverri",-1)])]),_:1}),e[12]||(e[12]=o(" 作者：",-1)),n(r,{href:"https://www.linkedin.com/pub/sadequl-hussain/14/711/1a7"},{default:s(()=>[...e[7]||(e[7]=[o("Sadequl Hussain",-1)])]),_:1}),e[13]||(e[13]=o(" 译者：",-1)),n(r,{href:"https://github.com/strugglingyouth"},{default:s(()=>[...e[8]||(e[8]=[o("strugglingyouth",-1)])]),_:1}),e[14]||(e[14]=o(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[9]||(e[9]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=o("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[15]||(e[15]=[o("LCTT",-1)])]),_:1}),e[18]||(e[18]=o(" 原创翻译，",-1)),n(r,{href:"https://linux.cn/"},{default:s(()=>[...e[16]||(e[16]=[o("Linux中国",-1)])]),_:1}),e[19]||(e[19]=o(" 荣誉推出",-1))])])}const T=i(d,[["render",g]]);export{C as __pageData,T as default};
